import sys
from itertools import permutations
from math import factorial

MOD = 998244353

data = sys.stdin.read().split()
n = int(data[0])
par = [0] * (n + 1)
kids = [[] for _ in range(n + 1)]
roots = []
for i in range(1, n + 1):
    par[i] = int(data[i])
    if par[i] == 0:
        roots.append(i)
    else:
        kids[par[i]].append(i)

# an order in which every seat comes after its accuser
top = []
stack = roots[:]
while stack:
    v = stack.pop()
    top.append(v)
    stack.extend(kids[v])

if n <= 8:
    tally = [0] * (n + 1)
    for perm in permutations(range(1, n + 1)):
        when = [0] * (n + 1)
        for t, v in enumerate(perm):
            when[v] = t
        if all(par[v] == 0 or when[par[v]] < when[v] for v in range(1, n + 1)):
            tally[perm[-1]] += 1
    print("\n".join(str(tally[v] % MOD) for v in range(1, n + 1)))
elif n <= 1200:
    # drop one seat, rebuild every subtree size from scratch, apply the forest count
    out = []
    f = factorial(n - 1) % MOD
    for x in range(1, n + 1):
        if kids[x]:
            out.append(0)
            continue
        size = [1] * (n + 1)
        for v in reversed(top):
            if v != x and par[v] and par[v] != x:
                size[par[v]] += size[v]
        prod = 1
        for v in range(1, n + 1):
            if v != x:
                prod = prod * size[v] % MOD
        out.append(f * pow(prod, MOD - 2, MOD) % MOD)
    print("\n".join(map(str, out)))
else:
    size = [1] * (n + 1)
    for v in reversed(top):
        if par[v]:
            size[par[v]] += size[v]
    prod = 1
    for v in range(1, n + 1):
        prod = prod * size[v] % MOD
    f = 1
    for i in range(2, n):
        f = f * i % MOD
    base = f * pow(prod, MOD - 2, MOD) % MOD
    cache = {}
    weight = [0] * (n + 1)
    out = [0] * (n + 1)
    for v in top:
        p = par[v]
        if p == 0:
            weight[v] = 1
        else:
            s = size[p]
            r = cache.get(s)
            if r is None:
                r = s * pow(s - 1, MOD - 2, MOD) % MOD
                cache[s] = r
            weight[v] = weight[p] * r % MOD
        if not kids[v]:
            out[v] = base * weight[v] % MOD
    print("\n".join(str(out[v]) for v in range(1, n + 1)))
